    PICSA_4712_02_HH := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_HH_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_HH := FALSE;
END_IF;
PICSA_4712_02_HH_Latch(S1 := PICSA_4712_02_HH,
                        R  := PICSA_4712_02_HH_Ack AND NOT PICSA_4712_02_HH);

IF PICSA_4712_02_Scaled >= PICSA_4712_02_H_SP THEN
    PICSA_4712_02_H := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_H_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_H := FALSE;
END_IF;

IF PICSA_4712_02_Scaled <= PICSA_4712_02_LL_SP THEN
    PICSA_4712_02_LL := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_LL_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_LL := FALSE;
END_IF;
PICSA_4712_02_LL_Latch(S1 := PICSA_4712_02_LL,
                        R  := PICSA_4712_02_LL_Ack AND NOT PICSA_4712_02_LL);

IF PICSA_4712_02_Scaled <= PICSA_4712_02_L_SP THEN
    PICSA_4712_02_L := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_L_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_L := FALSE;
END_IF;

IF PI_4712_01_Scaled >= PI_4712_01_HH_SP THEN
    PI_4712_01_HH := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_HH_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_HH := FALSE;
END_IF;
PI_4712_01_HH_Latch(S1 := PI_4712_01_HH,
                    R  := PI_4712_01_HH_Ack AND NOT PI_4712_01_HH);

IF PI_4712_01_Scaled >= PI_4712_01_H_SP THEN
    PI_4712_01_H := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_H_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_H := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_LL_SP THEN
    PI_4712_01_LL := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_LL_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_LL := FALSE;
END_IF;
PI_4712_01_LL_Latch(S1 := PI_4712_01_LL,
                    R  := PI_4712_01_LL_Ack AND NOT PI_4712_01_LL);

IF PI_4712_01_Scaled <= PI_4712_01_L_SP THEN
    PI_4712_01_L := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_L_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_L := FALSE;
END_IF;

IF TICSA_4750_03_HH OR TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := TRUE;
ELSIF LOOP_4750_03_TRIP AND MANUAL_RESET
      AND NOT TICSA_4750_03_HH AND NOT TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := FALSE;
END_IF;

IF PICSA_4712_02_HH OR PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := TRUE;
ELSIF LOOP_4712_02_TRIP AND MANUAL_RESET
      AND NOT PICSA_4712_02_HH AND NOT PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := FALSE;
END_IF;

IF SV_104_01_HH OR SV_104_01_LL THEN
    LOOP_104_01_TRIP := TRUE;
ELSIF LOOP_104_01_TRIP AND MANUAL_RESET
      AND NOT SV_104_01_HH AND NOT SV_104_01_LL THEN
    LOOP_104_01_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP OR LOOP_4750_03_TRIP OR LOOP_4712_02_TRIP OR LOOP_104_01_TRIP;

IF NOT SAFE_STATE THEN
    TICSA_4750_03_Error    := TICSA_4750_03_SP - TICSA_4750_03_Scaled;
    TICSA_4750_03_Integral := TICSA_4750_03_Integral + (TICSA_4750_03_Ki * TICSA_4750_03_Error);
    IF TICSA_4750_03_Integral > 100.0 THEN
        TICSA_4750_03_Integral := 100.0;
    ELSIF TICSA_4750_03_Integral < 0.0 THEN
        TICSA_4750_03_Integral := 0.0;
    END_IF;
    TICSA_4750_03_Output_Pct := (TICSA_4750_03_Kp * TICSA_4750_03_Error) + TICSA_4750_03_Integral;
    IF TICSA_4750_03_Output_Pct > 100.0 THEN
        TICSA_4750_03_Output_Pct := 100.0;
    ELSIF TICSA_4750_03_Output_Pct < 0.0 THEN
        TICSA_4750_03_Output_Pct := 0.0;
    END_IF;
    TV_4750_03_Out := REAL_TO_INT(6554.0 + (TICSA_4750_03_Output_Pct / 100.0) * (32767.0 - 6554.0));

    PICSA_4712_02_Error    := PICSA_4712_02_SP - PICSA_4712_02_Scaled;
    PICSA_4712_02_Integral := PICSA_4712_02_Integral + (PICSA_4712_02_Ki * PICSA_4712_02_Error);
    IF PICSA_4712_02_Integral > 100.0 THEN
        PICSA_4712_02_Integral := 100.0;
    ELSIF PICSA_4712_02_Integral < 0.0 THEN
        PICSA_4712_02_Integral := 0.0;
    END_IF;
    PICSA_4712_02_Output_Pct := (PICSA_4712_02_Kp * PICSA_4712_02_Error) + PICSA_4712_02_Integral;
    IF PICSA_4712_02_Output_Pct > 100.0 THEN
        PICSA_4712_02_Output_Pct := 100.0;
    ELSIF PICSA_4712_02_Output_Pct < 0.0 THEN
        PICSA_4712_02_Output_Pct := 0.0;
    END_IF;
    PVA_4712_02_Out := REAL_TO_INT(6554.0 + (PICSA_4712_02_Output_Pct / 100.0) * (32767.0 - 6554.0));

    SV_104_01_Out          := TRUE;
    HV_FC_4750_01_Out      := HS_4750_01;
    CV_75SA21_80_Out       := TRUE;
    ISOV_MNb_47121_Out     := TRUE;
    ISOV_MNb_47122_Out     := TRUE;
    ISOV_73KH12_50_UP_Out  := TRUE;
    ISOV_73KH12_50_DN_Out  := TRUE;
    ISOV_73KH12_25_Out     := TRUE;
    ISOV_Q_80_outlet_Out   := TRUE;
    ISOV_QSa_47140_Out     := TRUE;
    ISOV_QSb_47141_Out     := TRUE;
ELSE
    TV_4750_03_Out         := 6554;
    PVA_4712_02_Out        := 6554;
    SV_104_01_Out          := FALSE;
    HV_FC_4750_01_Out      := FALSE;
    CV_75SA21_80_Out       := FALSE;
    ISOV_MNb_47121_Out     := FALSE;
    ISOV_MNb_47122_Out     := FALSE;
    ISOV_73KH12_50_UP_Out  := FALSE;
    ISOV_73KH12_50_DN_Out  := FALSE;
    ISOV_73KH12_25_Out     := FALSE;
    ISOV_Q_80_outlet_Out   := FALSE;
    ISOV_QSa_47140_Out     := FALSE;
    ISOV_QSb_47141_Out     := FALSE;
END_IF;

System_Alarm :=
    TICSA_4750_03_HH_Latch.Q1 OR TICSA_4750_03_LL_Latch.Q1 OR
    TICSA_4750_03_HH           OR TICSA_4750_03_LL           OR
    TICSA_4750_03_H            OR TICSA_4750_03_L            OR
    PICSA_4712_02_HH_Latch.Q1 OR PICSA_4712_02_LL_Latch.Q1 OR
    PICSA_4712_02_HH           OR PICSA_4712_02_LL           OR
    PICSA_4712_02_H            OR PICSA_4712_02_L            OR
    PI_4712_01_HH_Latch.Q1    OR PI_4712_01_LL_Latch.Q1    OR
    PI_4712_01_HH              OR PI_4712_01_LL              OR
    PI_4712_01_H               OR PI_4712_01_L               OR
    LOOP_4750_03_TRIP          OR LOOP_4712_02_TRIP          OR
    LOOP_104_01_TRIP           OR SAFE_STATE;

END_PROGRAM
